"use strict";(globalThis.webpackChunkgrc||=[]).push([[42173],{94878(e){e.exports=JSON.parse('{"citeKey":"gurbani2005ubiquitousservices","slug":"gurbani-2005-ubiquitous-services-b0f5","title":"Ubiquitous Services in the Next Generation Network: Constraining and Facilitating Forces","authors":["V. K. Gurbani","A. Brusilovsky","X.-H. Sun"],"venue":"The Eurescom Summit 2005: Ubiquitous Services and Applications Exploiting the Potential, Heidelberg, Germany","type":"Conference","entryType":"inproceedings","date":"April, 2005","year":2005,"era":"iit","month":4,"abstract":"As envisioned some seven years ago, the Next Generation Network (NGN) with its emphasis on ubiquitous services was to revolutionize the lives of its users. The NGN, resulting from the merger of telecommunications, Information Technology (IT) and the Internet would provide on-demand, always-on services to its users. Service providers were to be affected by the increase in revenues paid by the users of these new services. Equipment vendors would have a difficult time keeping inventories of the NGN infrastructure. The truth has been somewhat different. In this paper, we characterize a set of constraining forces and as well as some positive facilitating forces acting on the NGN.","hasAbstract":true,"lede":"We characterize a set of constraining forces and as well as some positive facilitating forces acting on the NGN.","links":{"pdf":"https://grc.iit.edu/papers/2005/gurbani-2005-ubiquitous-services-b0f5.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);